/**
 * Typed access to the generated coordinate map.
 *
 * `anchors.json` is generated by `bun run tools/pdf/build-anchors.ts`. Never edit
 * it by hand: the generator records the source PDF hash, so a new edition of the
 * form is detected by re-running it (see `app/pdf/README.md`).
 */
import raw from "./anchors.json"

export type PageNumber = 1 | 2

/**
 * A line of text, baseline `yTop` from the page top. `xRight` anchors an RTL
 * (right-aligned) line; `xLeft` anchors an LTR line that must start at a fixed
 * left edge — used for the tail that follows the pre-printed deduction-file 9.
 */
export type TextAnchor = {
  page: PageNumber
  xRight?: number
  xLeft?: number
  yTop: number
  size?: number
  maxWidth?: number
}

/** Centre of a printed checkbox, `mark` is a literal discriminant. */
export type MarkAnchor = {
  page: PageNumber
  x: number
  y: number
  mark: true
  size?: number
}

/**
 * A printed cell grid: `cells` equal slots between `x0` and `x1`, writing
 * baseline `yTop`. `groups` documents the taller day/month separators; it is
 * informational because those ticks are already on the paper. `preprinted`
 * names characters the paper already carries (the deduction-file leading 9).
 */
export type CellAnchor = {
  page: PageNumber
  x0: number
  x1: number
  yTop: number
  cells: number
  size?: number
  groups?: number[]
  preprinted?: string
  fill?: "start" | "end" | "center"
}

export type Anchor = TextAnchor | MarkAnchor

export const ANCHORS = raw.anchors as Record<string, Anchor>
export const CELLS = (raw.cells ?? {}) as Record<string, CellAnchor>

export const ANCHOR_META = raw.source

/**
 * Signature area of section י (page 2), in points from the top-left.
 * The declaration's two writing lines are at y = 655.9; the signature rule is
 * 88 pt wide (34 → 122), so the strokes live just above it. Not generated
 * because it is an area, not a single text/box anchor.
 */
export const SIGNATURE_BOX = {
  page: 2 as PageNumber,
  x: 36,
  yTop: 640,
  width: 86,
  height: 14,
}

export function anchor(id: string): Anchor {
  const found = ANCHORS[id]
  if (!found) throw new Error(`Unknown PDF anchor: ${id}`)
  return found
}

export function cell(id: string): CellAnchor {
  const found = CELLS[id]
  if (!found) throw new Error(`Unknown PDF cell: ${id}`)
  return found
}

/** Narrows an anchor to a text slot (used by the overlay renderer). */
export function isTextAnchor(value: Anchor): value is TextAnchor {
  return "xRight" in value || "xLeft" in value
}
